#!/usr/bin/env python3
"""The y-axis — and an honest account of what it is not.

There are no outputs, no usage and no quality labels in the export, and (see
scripts/analyze_policy.py) model assignment is statistically independent of every
difficulty signal we can measure. So there is NO quality signal to recover from the
log itself. Anything plotted on the y-axis is one of:

  retention      PROXY. Share of calls left at a tier at least as capable as the one
                 that actually served them. Measures how conservative the route is,
                 NOT whether answers stayed good. Labelled as a proxy everywhere.

  exposure       RISK. Share of the hardest calls (top difficulty quartile) that were
                 downgraded. The number a reviewer should actually interrogate.

  judged         REAL, once you buy it. Per-request scores from a judge model, keyed
                 by request id, dropped in as JSON: {"<traj>_<idx>": 0.0..1.0}.
                 Because assignment is randomized within surface, a stratified sample
                 of a few hundred judged calls yields an UNBIASED opus-vs-sonnet
                 contrast by simple difference in means.
"""
import json
from pathlib import Path


def retention(routed, logged, capability_rank):
    """Fraction of calls routed to a tier >= the logged tier (proxy, not quality)."""
    if not routed:
        return 1.0
    ok = sum(1 for r, l in zip(routed, logged)
             if capability_rank.get(r, 0) >= capability_rank.get(l, 0))
    return ok / len(routed)


def downgrade_exposure(routed, logged, difficulties, capability_rank, hard_cut):
    """Share of HARD calls that were downgraded. Lower is safer."""
    hard = [(r, l) for r, l, d in zip(routed, logged, difficulties) if d >= hard_cut]
    if not hard:
        return 0.0
    return sum(1 for r, l in hard if capability_rank.get(r, 0) < capability_rank.get(l, 0)) / len(hard)


class JudgedScores:
    """Optional real quality axis. Absent by default — the repo says so rather than
    inventing numbers."""

    def __init__(self, scores=None):
        self.scores = scores or {}

    @classmethod
    def load(cls, path):
        p = Path(path)
        if not p.exists():
            return cls({})
        return cls(json.loads(p.read_text()))

    def __bool__(self):
        return bool(self.scores)

    def mean_for(self, request_ids):
        vals = [self.scores[i] for i in request_ids if i in self.scores]
        return (sum(vals) / len(vals)) if vals else None
